import json
from pathlib import Path
from typing import Any, Dict, List

def get_index_statistics(
    index_path: str
) -> Dict[str, Any]:
    """Get comprehensive statistics about a index.

Args:
    index_path: Path to the index file

Returns:
    Dictionary containing:
    {
        "total_passages": total number of passages,
        "metadata_fields": list of unique metadata field names,
        "field_value_counts": dictionary of field value counts
    }

Raises:
    FileNotFoundError: If index metadata file is not found"""

    # Check if metadata file exists
    meta_file_path = Path(index_path + ".meta.json")
    if not meta_file_path.exists():
        raise FileNotFoundError(f"Index metadata file not found: {meta_file_path}")

    # Load the metadata
    with open(meta_file_path, 'r', encoding='utf-8') as f:
        metadata = json.load(f)

    # Extract statistics from metadata
    total_passages = metadata.get("total_passages", 0)

    # Get unique metadata fields from all passages
    metadata_fields = set()
    field_value_counts = {}

    # Check if passages metadata is available in the index structure
    passages_metadata = metadata.get("passages_metadata", [])

    for passage_meta in passages_metadata:
        # Add all field names to the set
        for field_name in passage_meta.keys():
            metadata_fields.add(field_name)

            # Initialize field value counting if not exists
            if field_name not in field_value_counts:
                field_value_counts[field_name] = {}

            # Get the field value
            field_value = passage_meta.get(field_name)
            if field_value is not None:
                # Convert to string for counting
                value_str = str(field_value)
                field_value_counts[field_name][value_str] = field_value_counts[field_name].get(value_str, 0) + 1

    # If no passages metadata found, try to get basic info from index metadata
    if not passages_metadata:
        # Look for other metadata indicators
        if "index_stats" in metadata:
            index_stats = metadata["index_stats"]
            total_passages = index_stats.get("total_passages", total_passages)

        # Try to extract field information from other metadata sections
        for key, value in metadata.items():
            if key not in ["total_passages", "index_stats"] and isinstance(value, (dict, list)):
                metadata_fields.add(key)

    return {
        "total_passages": total_passages,
        "metadata_fields": list(metadata_fields),
        "field_value_counts": field_value_counts
    }

def analyze_index_coverage(index_path: str, required_fields: List[str]) -> Dict[str, Any]:
    """Analyze how well an index covers required metadata fields.

Args:
    index_path: Path to the index file
    required_fields: List of metadata field names that should be present

Returns:
    Dictionary containing:
    {
        "coverage_percentage": percentage of passages that have all required fields,
        "field_coverage": dictionary mapping field name to coverage percentage,
        "missing_fields": list of required fields not found in any passage
    }

Raises:
    FileNotFoundError: If index metadata file is not found"""

    # Check if metadata file exists
    meta_file_path = Path(index_path + ".meta.json")
    if not meta_file_path.exists():
        raise FileNotFoundError(f"Index metadata file not found: {meta_file_path}")

    # Load the metadata
    with open(meta_file_path, 'r', encoding='utf-8') as f:
        metadata = json.load(f)

    # Get passages metadata
    passages_metadata = metadata.get("passages_metadata", [])
    total_passages = len(passages_metadata)

    if total_passages == 0:
        # If no individual passage metadata, try to get total from index stats
        total_passages = metadata.get("total_passages", 0)

        # If we still can't get passage-level data, return basic analysis
        if total_passages == 0:
            # Check if required fields exist in the overall metadata
            existing_fields = []
            for field in required_fields:
                if field in metadata:
                    existing_fields.append(field)

            missing_fields = [field for field in required_fields if field not in existing_fields]

            return {
                "coverage_percentage": 100.0 if len(missing_fields) == 0 else 0.0,
                "field_coverage": {field: 100.0 if field in existing_fields else 0.0 
                                 for field in required_fields},
                "missing_fields": missing_fields
            }

    # Analyze coverage for each passage
    passages_with_all_fields = 0
    field_presence_count = {field: 0 for field in required_fields}

    for passage_meta in passages_metadata:
        # Check if this passage has all required fields
        has_all_fields = True

        for field in required_fields:
            if field in passage_meta and passage_meta[field] is not None:
                field_presence_count[field] += 1
            else:
                has_all_fields = False

        if has_all_fields:
            passages_with_all_fields += 1

    # Calculate percentages
    coverage_percentage = (passages_with_all_fields / total_passages * 100) if total_passages > 0 else 0.0
    field_coverage = {
        field: (count / total_passages * 100) if total_passages > 0 else 0.0
        for field, count in field_presence_count.items()
    }

    # Find missing fields (fields not present in any passage)
    missing_fields = [
        field for field in required_fields 
        if field_presence_count[field] == 0
    ]

    return {
        "coverage_percentage": coverage_percentage,
        "field_coverage": field_coverage,
        "missing_fields": missing_fields
    }
